package com.sonledev.enterprise.part3;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
@Slf4j
@Service
@RequiredArgsConstructor
public class EnterprisePart3Service {
private final ExternalApiClient apiClient;
private final EnterpriseRepository repository;
@Transactional(rollbackFor = Exception.class)
public BusinessResponse executeEnterpriseProcess(BusinessRequest request) {
log.info("Starting enterprise execution for process part 3 with ID: {}", request.getI
d());
// Validate domain invariants
validateRequest(request);
// Execute core business logic
var entity = repository.findById(request.getId())
.orElseThrow(() -> new ResourceNotFoundException("Entity not found: " + request.g
etId()));
entity.updateStatus(BusinessStatus.PROCESSING);
repository.save(entity);
log.info("Successfully completed process part 3");
return new BusinessResponse(entity.getId(), "SUCCESS", System.currentTimeMillis());
}
private void validateRequest(BusinessRequest request) {
if (request == null || request.getId() == null) {
throw new IllegalArgumentException("Invalid request payload for part 3");
}
}
}
3. Luu y quan trong va Best Practices:
• Luon su dung DTO (Data Transfer Object) de truyen tai du lieu giua cac layer, tranh expose truc tiep
Entity ra ngoai tang presentation.
• Cau hinh transactional boundary ro rang tren tang Service de dam bo tinh toan v■n du lieu (ACID) khi ket
noi voi PostgreSQL/MySQL.
• Su dung MDC va Distributed Tracing de quan ly log tap trung trong kien truc Microservices phan tan.
